// Everything below is transcribed from the Source SDK 2013 TF code; each constant names
// the definition it mirrors. Numbers are SDK defaults (convars at their default values).

/** SimpleSpline (mathlib): 3x² − 2x³, the S-curve the damage spread is shaped with. */
export function simpleSpline(x: number): number {
  const x2 = x * x;
  return 3 * x2 - 2 * x2 * x;
}

/** SimpleSplineRemapValClamped (mathlib). */
export function simpleSplineRemapValClamped(
  val: number,
  a: number,
  b: number,
  c: number,
  d: number,
): number {
  if (a === b) return val >= b ? d : c;
  const t = Math.min(1, Math.max(0, (val - a) / (b - a)));
  return c + (d - c) * simpleSpline(t);
}

/** RemapValClamped (mathlib). */
export function remapValClamped(val: number, a: number, b: number, c: number, d: number): number {
  if (a === b) return val >= b ? d : c;
  const t = Math.min(1, Math.max(0, (val - a) / (b - a)));
  return c + (d - c) * t;
}

// --- Critical hits ------------------------------------------------------------

/** tf_shareddefs.h TF_DAMAGE_CRIT_* plus the crit bucket convars (basecombatweapon_shared.cpp). */
export const CRIT = {
  /** TF_DAMAGE_CRIT_CHANCE: per-shot random crit chance (× the crit multiplier below). */
  chance: 0.02,
  /** TF_DAMAGE_CRIT_CHANCE_RAPID: target fraction of time spent critting for rapid-fire weapons. */
  chanceRapid: 0.02,
  /** TF_DAMAGE_CRIT_DURATION_RAPID: length of a rapid-fire crit burst, seconds. */
  rapidDuration: 2,
  /** Rapid-fire weapons roll at most once per this many seconds (CalcIsAttackCriticalHelper). */
  rapidCheckInterval: 1,
  /** TF_DAMAGE_CRIT_CHANCE_MELEE. */
  chanceMelee: 0.15,
  /** TF_DAMAGE_CRIT_MULTIPLIER. */
  multiplier: 3,
  /** TF_DAMAGE_MINICRIT_MULTIPLIER. */
  miniCritMultiplier: 1.35,
  /** WEAPON_RANDOM_RANGE: rolls are RandomInt(0, 9999) < chance × 10000. */
  randomRange: 10000,
  /**
   * Damage dealt recently raises the chance (CTFPlayerShared::UpdateCritMult): damage events
   * 2–20 s old count (tracked for 30 s); 800 damage reaches the cap.
   */
  critMod: { minTime: 2, maxTime: 20, trackFor: 30, damage: 800, maxMult: 6 },
  /**
   * Anti-cheat token bucket (tf_weapon_criticals_bucket_*): every attack adds its base damage
   * (× bullets) up to `cap`; a crit withdraws damage × 3 × cost multiplier (melee 0.5, ranged
   * 1→3 as the share of rolls that asked for a crit goes 0.1→1). A crit the bucket cannot pay
   * for is refused. Rapid-fire crits pay for the whole burst up front.
   */
  bucket: { cap: 1000, bottom: -250, initial: 300, meleeCostMult: 0.5, rangedCostMultMax: 3 },
  /** CanFireRandomCriticalShot: refuse when the observed crit rate exceeds chance + 0.1. */
  observedChanceSlack: 0.1,
} as const;

/**
 * The crit chance multiplier from recent damage (CTFPlayerShared::UpdateCritMult +
 * GetCritMult): the damage is quantised to a byte, and the multiplier runs 1 → 4
 * (TF_DAMAGE_CRITMOD_MAXMULT 6 is only the byte's encoding range) — so a fresh player
 * crits 2% of shots and one with 800+ recent damage 8%; melee 15% → 60%.
 */
export function critChanceMultiplier(recentDamage: number): number {
  const byte = Math.floor(remapValClamped(recentDamage, 0, CRIT.critMod.damage, 0, 255));
  return remapValClamped(byte, 0, 255, 1, 4);
}

/** Chance per check (once a second) that a rapid-fire weapon starts a 2 s crit burst. */
export function rapidFireCritStartChance(critMult: number): number {
  const total = Math.min(0.99, Math.max(0.01, CRIT.chanceRapid * critMult));
  const nonCritDuration = CRIT.rapidDuration / total - CRIT.rapidDuration;
  return 1 / nonCritDuration;
}

// --- Damage spread and distance modifier --------------------------------------

/** CTFGameRules::ApplyOnDamageModifyRules distance/spread constants. */
export const DAMAGE_SPREAD = {
  /** tf_damage_range: the ± fraction of base damage the modifier spans. */
  range: 0.5,
  /** flRandomDamageSpread: half-width of the random window around the distance centre. */
  randomSpread: 0.1,
  /** tf_damage_disablespread defaults to 1: the window's centre is used, no randomness. */
  disableSpread: true,
  /** flOptimalDistance: distance at which the modifier is neutral (×2 reaches full falloff). */
  optimalDistance: 512,
  /** Sniper rifles use 2.5 × the optimal distance. */
  sniperOptimalDistanceMult: 2.5,
  /** Sentry bullets use SENTRY_MAX_RANGE as the optimal distance. */
  sentryOptimalDistance: 1100,
  /** DMG_NOCLOSEDISTANCEMOD caps the close-range centre at 0.65 (from 1). */
  noCloseCentreMax: 0.65,
  /** Rockets (incl. Direct Hit, Cow Mangler): ramp-up halved -> 125% max. */
  rocketRampUpMult: 0.5,
  /** Grenade/sticky launchers without DMG_NOCLOSEDISTANCEMOD: whole range × 0.2 (±10%). */
  grenadeRangeMult: 0.2,
  /** Scattergun-family close range: ramp-up × 1.5 -> 175% max. */
  scattergunRampUpMult: 1.5,
} as const;

export type CritKind = 'none' | 'mini' | 'full';

export interface DistanceModInput {
  /** Damage before the modifier (after per-weapon falloff such as radius damage). */
  damage: number;
  /** World-space-centre distance attacker -> victim. */
  distance: number;
  /** The hit's DMG_* bits. */
  damageType: number;
  /** ETFWeaponType of the attacking weapon (weapons.ts TF_WEAPON_IDS), or -1. */
  weaponId: number;
  crit: CritKind;
  /** Override the optimal distance (sniper rifles, sentries). Default 512. */
  optimalDistance?: number;
  /** 0..1 roll inside the spread window; ignored while DAMAGE_SPREAD.disableSpread. */
  random01?: number;
}

const {
  TF_WEAPON_ROCKETLAUNCHER,
  TF_WEAPON_ROCKETLAUNCHER_DIRECTHIT,
  TF_WEAPON_PARTICLE_CANNON,
  TF_WEAPON_PIPEBOMBLAUNCHER,
  TF_WEAPON_GRENADELAUNCHER,
  TF_WEAPON_CANNON,
  TF_WEAPON_STICKBOMB,
  TF_WEAPON_SCATTERGUN,
  TF_WEAPON_SODA_POPPER,
  TF_WEAPON_PEP_BRAWLER_BLASTER,
} = TF_WEAPON_IDS;

/**
 * Final damage of one hit on a player by another (ApplyOnDamageModifyRules, the
 * distance/spread + crit section): ramp-up up close, falloff at range, then ×3 for crits
 * (no ramp-up or falloff) or ×1.35 for mini-crits (ramp-up but no falloff). Self-damage
 * and DMG_FALL/DMG_DROWN skip this step entirely.
 */
export function applyDistanceAndCrit(input: DistanceModInput): number {
  const { damageType, weaponId, crit } = input;
  let damage = input.damage;
  const isCrit = crit === 'full';
  // SDK: bDoShortRangeDistanceIncrease = !bCrit || mini; bDoLongRangeDistanceDecrease = !bCrit && !mini.
  const shortRangeIncrease = !isCrit;
  const longRangeDecrease = crit === 'none';
  let randomDamage = input.damage * DAMAGE_SPREAD.range;
  const spread = DAMAGE_SPREAD.randomSpread;
  let min = 0.5 - spread;
  let max = 0.5 + spread;
  if (damageType & TF_DMG.DMG_USEDISTANCEMOD) {
    const optimal = input.optimalDistance ?? DAMAGE_SPREAD.optimalDistance;
    const distance = Math.max(1, input.distance);
    let centre = remapValClamped(distance / optimal, 0, 2, 1, 0);
    if ((centre > 0.5 && shortRangeIncrease) || centre <= 0.5) {
      if (damageType & TF_DMG.DMG_NOCLOSEDISTANCEMOD && centre > 0.5) {
        centre = 0.5 + ((centre - 0.5) / 0.5) * (DAMAGE_SPREAD.noCloseCentreMax - 0.5);
      }
      min = Math.max(0, centre - spread);
      max = Math.min(1, centre + spread);
    }
  }
  const roll = DAMAGE_SPREAD.disableSpread
    ? min + spread
    : min + (max - min) * (input.random01 ?? 0.5);
  switch (weaponId) {
    case TF_WEAPON_ROCKETLAUNCHER:
    case TF_WEAPON_ROCKETLAUNCHER_DIRECTHIT:
    case TF_WEAPON_PARTICLE_CANNON:
      if (roll > 0.5) randomDamage *= DAMAGE_SPREAD.rocketRampUpMult;
      break;
    case TF_WEAPON_PIPEBOMBLAUNCHER:
    case TF_WEAPON_GRENADELAUNCHER:
    case TF_WEAPON_CANNON:
    case TF_WEAPON_STICKBOMB:
      if (!(damageType & TF_DMG.DMG_NOCLOSEDISTANCEMOD)) randomDamage *= DAMAGE_SPREAD.grenadeRangeMult;
      break;
    case TF_WEAPON_SCATTERGUN:
    case TF_WEAPON_SODA_POPPER:
    case TF_WEAPON_PEP_BRAWLER_BLASTER:
      if (roll > 0.5) randomDamage *= DAMAGE_SPREAD.scattergunRampUpMult;
      break;
  }
  const variance = simpleSplineRemapValClamped(roll, 0, 1, -randomDamage, randomDamage);
  if ((shortRangeIncrease && variance > 0) || longRangeDecrease) damage += variance;
  if (crit === 'mini') damage += (CRIT.miniCritMultiplier - 1) * damage;
  else if (isCrit) damage += (CRIT.multiplier - 1) * damage;
  return damage;
}

// --- Radius (blast) damage -----------------------------------------------------

/** CTFRadiusDamageInfo / CTFGameRules::RadiusDamage. */
export const RADIUS_DAMAGE = {
  /** TF_ROCKET_RADIUS (tf_weaponbase_rocket.h): blast radius vs everyone else. */
  rocketRadius: 146,
  /**
   * TF_ROCKET_RADIUS_FOR_RJS = 110 × 1.1: rockets apply to their own shooter with this radius
   * and the weapon script's base damage, so every launcher rocket-jumps like the stock one.
   */
  rocketSelfRadius: 121,
  /** TF_GRENADE_JUMP_RADIUS (tf_weaponbase_grenadeproj.cpp): the same for pipes and stickies. */
  grenadeSelfRadius: 146,
  /** Falloff with DMG_HALF_FALLOFF: damage at the edge = 50%. */
  halfFalloff: 0.5,
  /** Self-damage from your own pipes/stickies (TF_WEAPON_PIPEBOMBLAUNCHER/GRENADELAUNCHER/CANNON/STICKBOMB). */
  demoSelfDamageScale: 0.75,
} as const;

/**
 * Blast damage at `distance` (RadiusDamage → ApplyToEntity): linear from full damage at the
 * centre to damage × falloff at the radius, where falloff is 0 with DMG_RADIUS_MAX, 0.5 with
 * DMG_HALF_FALLOFF, else damage / radius. Distance to a player is the smaller of the
 * distances to its origin and to its world-space centre; the entity a projectile hit
 * directly takes distance 0.
 */
export function radiusDamageAt(
  damage: number,
  radius: number,
  distance: number,
  damageType: number,
): number {
  let falloff: number;
  if (damageType & TF_DMG.DMG_RADIUS_MAX) falloff = 0;
  else if (damageType & TF_DMG.DMG_HALF_FALLOFF) falloff = RADIUS_DAMAGE.halfFalloff;
  else if (radius) falloff = damage / radius;
  else falloff = 1;
  return remapValClamped(distance, 0, radius, damage, damage * falloff);
}

// --- Knockback ---------------------------------------------------------------------

/** CTFPlayer::ApplyPushFromDamage scales (tf_player.cpp). */
export const KNOCKBACK = {
  /** tf_damageforcescale_other: damage from someone else. */
  other: 6,
  /** tf_damageforcescale_self_soldier_rj: Soldier hit by his own blast while airborne. */
  selfSoldierAirborne: 10,
  /** tf_damageforcescale_self_soldier_badrj: ...while on the ground. */
  selfSoldierGrounded: 5,
  /** DAMAGE_FORCE_SCALE_SELF: everyone else's self blast (sticky jumps). */
  self: 9,
  /** Soldier's own non-blast self-damage pushes nothing. */
  selfSoldierNonBlast: 0,
  /** Sentry bullets (CObjectSentrygun::GetPushMultiplier default). */
  sentryBullet: 16,
  /** Heavies take half the push from anything but sentries. */
  heavyMult: 0.5,
  /** Crouched self-blast uses a 55-unit tall hull in the force formula (more push). */
  crouchedSelfHullZ: 55,
  /** DamageForce clamps the push speed. */
  maxForce: 1000,
} as const;

/**
 * DamageForce (tf_player.cpp): push speed added along the blast/bullet direction, from the
 * damage and the victim's hull size (48×48×82 standing).
 */
export function damageForce(
  size: { x: number; y: number; z: number },
  damage: number,
  scale: number,
): number {
  const force = damage * ((48 * 48 * 82.0) / (size.x * size.y * size.z)) * scale;
  return Math.min(force, KNOCKBACK.maxForce);
}

// --- Self damage, fall damage, afterburn ----------------------------------------------

/** tf_damagescale_self_soldier: a Soldier's own blast while airborne (rocket jump) does 60%. */
export const SOLDIER_ROCKET_JUMP_SELF_DAMAGE_SCALE = 0.6;

/** CTFGameRules::FlPlayerFallDamage (tf_gamerules.cpp). */
export const FALL_DAMAGE = {
  /** TF_PLAYER_MAX_SAFE_FALL_SPEED. */
  maxSafeSpeed: 650,
  /** Old TFC formula: 5 × (fall speed / 300) × (max health / 100). */
  perSpeed: 5 / 300,
  /** Random ×0.8…1.2 (tf_fall_damage_disablespread 0). */
  randomMin: 0.8,
  randomMax: 1.2,
} as const;

/** Fall damage for a landing at `fallSpeed` (random01 picks within the 0.8–1.2 spread). */
export function fallDamage(fallSpeed: number, maxHealth: number, random01 = 0.5): number {
  if (fallSpeed <= FALL_DAMAGE.maxSafeSpeed) return 0;
  const spread = FALL_DAMAGE.randomMin + (FALL_DAMAGE.randomMax - FALL_DAMAGE.randomMin) * random01;
  return FALL_DAMAGE.perSpeed * fallSpeed * (maxHealth / 100) * spread;
}

/** Afterburn (tf_shareddefs.h TF_BURNING_*, tf_player_shared.cpp Burn / ConditionThink). */
export const AFTERBURN = {
  /** TF_BURNING_FREQUENCY: a tick every 0.5 s... */
  interval: 0.5,
  /** TF_BURNING_DMG: ...of 4 damage (8/s), DMG_BURN | DMG_PREVENT_PHYSICS_FORCE, TF_DMG_CUSTOM_BURNING. */
  damage: 4,
  /** tf_afterburn_max_duration: duration stacks up to 10 s. */
  maxDuration: 10,
  /** Pyros (immune) still show a 0.25 s burn (TF_BURNING_FLAME_LIFE_PYRO). */
  pyroDuration: 0.25,
  /** Each tick removes this much remaining duration. */
  durationPerTick: 0.5,
} as const;

